#include <bits/stdc++.h>
using namespace std;

class AReader {
private:
    std::stringstream ss;
public:
    AReader() {}
    bool hasNext() {
        while (ss.rdbuf()->in_avail() == 0) {
            std::string line;
            if (!std::getline(std::cin, line))
                return false;
            ss.clear();
            ss.str(line);
        }
        return true;
    }
    std::string next() {
        hasNext();
        std::string token;
        ss >> token;
        return token;
    }
    int nextInt() {
        return std::stoi(next());
    }
    long long nextLong() {
        return std::stoll(next());
    }
    double nextDouble() {
        return std::stod(next());
    }
};

int res = 0;
int X = 0;
int n;
char cs[1000];

void dfs(int u, int s) {
    if (u >= n) {
        if (s % 25 == 0) res++;
        return;
    }
    int t = cs[u] - '0';
    if (t >= 0 && t <= 9) {
        dfs(u + 1, s * 10 + t);
    } else if (cs[u] == 'X') {
        dfs(u + 1, s * 10 + X);
    } else {
        if (u == n - 1) {
            dfs(u + 1, s * 10 + 5);
            dfs(u + 1, s * 10);
        } else {
            for (int i = 0; i < 10; i++) {
                if (i == 0 && u == 0) continue;
                dfs(u + 1, s * 10 + i);
            }
        }
    }
}

void solve() {
    AReader scan;
    std::string input_str = scan.next();
    n = (int)input_str.size();
    for (int i = 0; i < n; i++) {
        cs[i] = input_str[i];
    }
    bool flag = false;
    for (int i = 0; i < n; i++) {
        if (cs[i] == 'X') {
            flag = true;
            break;
        }
    }
    if (cs[0] == '0' && n != 1) {
        std::cout << 0 << "\n";
        return;
    }
    if (flag) {
        for (int i = 0; i < 10; i++) {
            if (cs[0] == 'X' && n > 1 && i == 0) continue;
            X = i;
            dfs(0, 0);
        }
    } else {
        dfs(0, 0);
    }
    std::cout << res << "\n";
}

int main() {
    solve();
    return 0;
}

